 4	/**
 5	 * Shared movement template for organisms that search adjacent cells for a target,
 6	 * move toward it when found, and otherwise fall back to free or grass-adjacent
 7	 * locations.
 8	 */
 9	public abstract class MobileForager extends Organism
10	{
11	    protected static final Random rand = Randomizer.getRandom();
12	
13	    public MobileForager(Field field, Location location)
14	    {
15	        super(field, location);
16	    }
17	
18	    /**
19	     * Template method for target acquisition and movement.
20	     */
21	    protected final void forageAndMove()
22	    {
23	        Location targetLocation = locateTargetLocation();
24	        if(targetLocation == null) {
25	            targetLocation = getField().freeAdjacentLocation(getLocation());
26	        }
27	
28	        if(targetLocation != null) {
29	            setLocation(targetLocation);
30	            return;
31	        }
32	
33	        List<Location> fallbackLocations = getFallbackLocations();
34	        if(!fallbackLocations.isEmpty()) {
35	            getField().clear(getLocation());
36	            setLocation(fallbackLocations.get(rand.nextInt(fallbackLocations.size())));
37	            return;
38	        }
39	
40	        onMovementBlocked();
41	    }
42	
43	    /**
44	     * Find the resource or prey the organism is seeking.
45	     */
46	    protected abstract Location locateTargetLocation();
47	
48	    /**
49	     * Hook for species-specific fallback movement targets.
50	     */
51	    protected List<Location> getFallbackLocations()
52	    {
53	        return getField().adjacentLocationsWithSpecies(getLocation(), Grass.class);
54	    }
55	
56	    /**
57	     * Hook for what to do when movement is impossible.
58	     */
59	    protected void onMovementBlocked()
60	    {
61	        setDead();
62	    }
63	}

