  4	/**
  5	 * A class representing shared characteristics of animals.
  6	 *
  7	 * @version 2022.03.02
  8	 */
  9	public abstract class Animal extends MobileForager implements Edible
 10	{
 11	
 12	    protected int age;
 13	    protected boolean isNocturnal;
 14	    protected int foodLevel;
 15	    protected Gender sex;
 16	
 17	    // An animal is either male or female 
 18	    protected enum Gender {
 19	        MALE,
 20	        FEMALE
 21	    }
 22	    // An animal's chance of contracting a disease at birth
 23	    private static final double RANDOM_CONTRACTION_RATE = 0.002;
 24	
 25	
 26	    // Declaring abstract methods to obtain fields used by subclasses.
 27	    // These methods are implemented by each species.
 28	    protected abstract double BREEDING_AGE();
 29	    protected abstract int MAX_LITTER_SIZE();
 30	    protected abstract double BREEDING_PROBABILITY();
 31	    protected abstract int MAX_AGE();
 32	    protected abstract int MAX_FOOD_LEVEL();
 33	    protected abstract Set<Class<?>> DIET();
 34	
 35	
 36	    /**
 37	     * Create a new animal at location in field.
 38	     *
 39	     * @param field The field currently occupied.
 40	     * @param location The location within the field.
 41	     * @param randomAge The animal's random starting age.
 42	     * @param sex The animal's gender. 
 43	     */
 44	    public Animal(Field field, Location location, boolean randomAge, Gender sex)
 45	    {
 46	        super(field, location);
 47	        this.sex = sex;
 48	        if(randomAge) {
 49	            this.age = rand.nextInt(MAX_AGE());
 50	            foodLevel = rand.nextInt(MAX_FOOD_LEVEL());
 51	        }
 52	        else {
 53	            this.age = 0;
 54	            foodLevel = MAX_FOOD_LEVEL();
 55	        }
 56	        randomlyContractDisease();
 57	    }
 58	
 59	    /**
 60	     * Make this animal act - that is: make it do
 61	     * whatever it wants/needs to do.
 62	     * @param newAnimals A list to receive newly born animals.
 63	     * @param environment The environment that the animal resides in.
 64	     */
 65	    public void act(List<Actor> newAnimals, Environment environment)
 66	    {
 67	        randomlyContractDisease();
 68	        incrementAge();
 69	        incrementHunger();
 70	        if(isAlive()) {
 71	            giveBirth(newAnimals, environment);
 72	            forageAndMove();
 73	
 74	            if(isDiseased() && getDisease().getLethalityRate() <= rand.nextDouble()){
 75	                // every step, check if the Animal is diseased
 76	                // if it is Diseased, and a random double is less than the lethality rate, the Animal dies
 77	                setDead();
 78	            }
 79	
 80	        }
 81	    }
 82	
 83	    /**
 84	     * Look for food adjacent to the current location.
 85	     * Only the first food is eaten.
 86	     * @return Where food was found, or null if it wasn't.
 87	     */
 88	    protected Location findFood()
 89	    {
 90	        Field field = getField();
 91	        List<Location> adjacent = field.adjacentLocations(getLocation());
 92	        for(Location loc : adjacent){
 93	            if(field.getObjectAt(loc) != null && !(field.getObjectAt(loc) instanceof Hunter)){
 94	                    Organism organism = (Organism) field.getObjectAt(loc);
 95	                    if (organism.isDiseased() && organism.getDisease().getDiseaseType() != DiseaseType.CONTACT && organism.getDisease().getPropagationRate() <= rand.nextDouble()){
 96	                        // contracts the first contact disease it encounters amongst the adjacent animals
 97	                        this.setDisease(organism.getDisease());
 98	                        break;
 99	                    }
100	                }
101	        }
102	        Iterator<Location> it = adjacent.iterator();
103	        // only eats if it's not full (food level less than max)
104	        while(it.hasNext() && foodLevel <= MAX_FOOD_LEVEL()) {
105	            Location where = it.next();
106	            Object animal = field.getObjectAt(where);
107	            if(animal instanceof Edible && DIET().contains(animal.getClass()))
108	            {
109	                Organism food = (Organism) animal;
110	                if (food.isDiseased() &&  food.getDisease().getDiseaseType() == DiseaseType.FOODBORNE && food.getDisease().getPropagationRate() <= rand.nextDouble()) 
111	                {
112	                    // contracts disease from food if it has a disease and that disease is foodborne
113	                    setDisease(food.getDisease());
114	                }
115	                if(food.isAlive()) 
116	                {
117	                    food.setDead();
118	                    int newFoodLevel = foodLevel + ((Edible) food).getFoodValue();
119	
120	                    // caps the food level at the maximum
121	                    foodLevel = Math.min(newFoodLevel, MAX_FOOD_LEVEL());
122	
123	                    return where;
124	                }
125	                return where;
126	            }
127	        }
128	        return null;
129	    }
130	
131	    /**
132	     * Returns true if an animal contracts a disease at birth.
133	     * Returns false if otherwise. 
134	     */
135	    protected void randomlyContractDisease()
136	    {
137	        if(rand.nextDouble() <= RANDOM_CONTRACTION_RATE) {
138	            setDisease(new Disease());
139	        }
140	    }
141	
142	    /**
143	     * Check whether this animal is to give birth at this step.
144	     * New births will be made into free adjacent locations.
145	     * @param newAnimals A list to return newly born animals.
146	     * @param environment The environment that the animal resides in. 
147	     */
148	    protected abstract void giveBirth(List<Actor> newAnimals, Environment environment);
149	
150	    @Override
151	    protected Location locateTargetLocation()
152	    {
153	        return findFood();
154	    }
