156	    /**
157	     * Returns true if the animal is awake or not.
158	     */
159	    public boolean isAwake(Environment environment)
160	    {
161	        if(isNocturnal){
162	            return !environment.getTime().isDay();
163	        }
164	        return environment.getTime().isDay();
165	    }
