167	    /**
168	     * Generates a number representing the number of births,
169	     * if it can breed.
170	     * @return The number of births (may be zero)
171	     */
172	    protected int breed()
173	    {
174	        int births = 0;
175	        if(canBreed() && rand.nextDouble() <= BREEDING_PROBABILITY()) {
176	            births = rand.nextInt(MAX_LITTER_SIZE()) + 1;
177	            Animal mate = (Animal) getPotentialMates().get(rand.nextInt(getPotentialMates().size()));
178	            if(mate.isDiseased() && mate.getDisease().getDiseaseType() == DiseaseType.SEXUAL){
179	                this.setDisease(mate.getDisease());
180	            }
181	        }
182	        return births;
183	    }
184	
185	    /**
186	     * Returns true if the animal is able to breed.
187	     * Returns false if otherwise. 
188	     */
189	    protected boolean canBreed()
190	    {
191	        return (age >= BREEDING_AGE() && getPotentialMates().size() > 0);
192	    }
193	
194	    /**
195	     * Returns a list of potential mates. Mates have to be
196	     * of a opposite gender. 
197	     * @return List<Organism> A list of potential mates.
198	     */
199	    protected List<Organism> getPotentialMates()
200	    {
201	        List<Organism> potentialMates = new ArrayList<>();
202	        if(getField() != null){
203	            potentialMates = getField().adjacentLocations(getLocation()).stream()
204	                    .map(s -> getField().getObjectAt(s))
205	                    .filter(s -> s != null)
206	                    .filter(s -> s.getClass().equals(this.getClass()))
207	                    .filter(s -> this.sex != ((Animal) s).sex)
208	                    .map(s -> (Organism) s)
209	                    .collect(Collectors.toList());
210	            // stream counts the number of Animals of the same species, as well as opposite gender
211	        }
212	        return potentialMates;
213	    }
