217	     * Increase the age. This could result in the animal's death.
218	     */
219	    protected void incrementAge()
220	    {
221	        this.age++;
222	        if(this.age > MAX_AGE()) {
223	            setDead();
224	        }
225	    }
226	
227	    /**
228	     * Make this animal more hungry. This could result in the animal's death.
229	     */
230	    protected void incrementHunger()
231	    {
232	        foodLevel--;
233	        if(foodLevel <= 0) {
234	            setDead();
235	        }
236	    }
